CREATE TABLE native_current_trends (city_slug TEXT PRIMARY KEY NOT NULL CHECK(city_slug IN ('tokyo')), week_start TEXT NOT NULL, observed_at INTEGER NOT NULL CHECK(observed_at > 0), expires_at INTEGER NOT NULL CHECK(expires_at > observed_at AND expires_at - observed_at <= 86400000), review_id TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload) AND length(CAST(payload AS BLOB)) <= 65536));
